  "<div class=\"bulk-builder-empty-title\">No panel connection</div>": "<div class=\"bulk-builder-empty-title\">Нет подключения к панели</div>",
  "<div class=\"bulk-builder-empty-sub\">The product library is available when the editor is opened with a design from the panel. In this tab, you can use the Excel or AI source.</div>": "<div class=\"bulk-builder-empty-sub\">Библиотека товаров доступна, если открыть редактор с дизайном из панели. На этой вкладке можно использовать источник Excel или ИИ.</div>",
