  "No panel connection.": "Нет подключения к панели.",
  "Select an object on … assign <strong>Design Field</strong> (e.g. title, image, price) from the right panel. Then come back here; let AI or Excel multiply those fields.</div>": "Выберите объект на рабочем поле… назначьте ему <strong>поле дизайна</strong> (например, название, изображение или цену) на правой панели. Затем вернитесь сюда и позвольте AI или Excel размножить эти поля.</div>",
  "Select from your panel's product library; name, price, image and attributes will fill the fields automatically.": "Выберите из библиотеки продуктов вашей панели; имя, цена, изображение и атрибуты заполнятся автоматически.",
