  "<span>First assign a Design Field to at least one object in the design (right panel), then AI will fill them.</span></div></div>": "<span>Сначала назначьте поле дизайна хотя бы одному объекту в дизайне (правая панель), затем ИИ заполнит их.</span></div></div>",
  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "Этот запрос исходит от Bulk Builder (проход PLAN). Прочтите инструкции и поля дизайна, затем СПИСЬТЕ результаты, которые вы будете производить, ТОЛЬКО ЭТИКЕТКИ (без содержания полей). Возвращайте ТОЛЬКО необработанный объект JSON: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Если параметр «перевод» равен true, метки представляют собой НАЗВАНИЯ ЯЗЫКОВ (написанные на том же языке, который использовал пользователь). В противном случае метки представляют собой отдельную короткую тему/начальное слово для каждого вывода. Соблюдайте любое количество, указанное в инструкции; в остальном разумный набор (примерно от 6 до 12). Жесткий лимит 500.\n",
  "Preparing plan...": "Готовим план...",
