  "This app could not reach dika studio just now, so the full sign-up flow is not available.": "Приложению не удалось сейчас подключиться к dika studio, поэтому полная регистрация недоступна.",
  "You can carry on using the editor: everything except the online library works offline.": "Вы можете продолжать пользоваться редактором: все, кроме онлайн-библиотеки, работает в автономном режиме.",
  "It will ask again next time you open it.": "Он спросит еще раз, когда вы откроете его в следующий раз.",
  "Registration wizard": "Мастер регистрации",
  "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>": "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">дика студия</div>",
  "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Multi-Product Design Platform</div>": "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Платформа дизайна нескольких товаров</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Версия 2.0</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Built by <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Создано <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Released under the Business Source License 1.1.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">© 2026 Агентство Mirex. Выпущено под лицензией Business Source License 1.1.</div>.",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Reset clears only the wizard's own record. Your projects, settings and keys are untouched.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Сброс удаляет только запись мастера. Проекты, настройки и ключи не изменяются.</div>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Need help? Contact us:</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Нужна помощь? Свяжитесь с нами:</p>",
  "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visit our website</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Посетить наш сайт</a></div>",
  "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Email support@dika.studio</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Написать на support@dika.studio</a></div>",
  "settings: about": "настройки: о",
  "<div class=\"settings-field\" id=\"account-panel\" style=\"margin-bottom:18px\">": "<div class=\"settings-field\" id=\"account-panel\" style=\"margin-bottom:18px\">",
  "<div style=\"font-size:12px;color:var(--text-dim);line-height:1.7\">": "<div style=\"font-size:12px;color:var(--text-dim);line-height:1.7\">",
  "<div>Plan: ": "<div>Тариф: ",
  "<button type=\"button\" class=\"btn-xs\" id=\"account-manage\" style=\"padding:7px 14px;background:var(--surface3);border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Manage account</button>": "<button type=\"button\" class=\"btn-xs\" id=\"account-manage\" style=\"padding:7px 14px;background:var(--surface3);border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Управление аккаунтом</button>",
  "<button type=\"button\" class=\"btn-xs\" id=\"account-signout\" style=\"padding:7px 14px;background:transparent;border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Sign out</button>": "<button type=\"button\" class=\"btn-xs\" id=\"account-signout\" style=\"padding:7px 14px;background:transparent;border:1px solid var(--border);border-radius:4px;color:var(--text-dim);cursor:pointer;font-size:12px\">Выйти</button>",
  "<p style=\"font-size:11px;color:var(--text-faint);margin-top:8px;line-height:1.5\">": "<p style=\"font-size:11px;color:var(--text-faint);margin-top:8px;line-height:1.5\">",
  "<div style=\"color:var(--text-faint)\">Nothing about your designs. No document, no title, no file name, no image.</div>": "<div style=\"color:var(--text-faint)\">Нет информации о дизайнах: документа, заголовка, имени файла или изображения.</div>",
  "<div style=\"margin-top:6px;font-family:ui-monospace,Menlo,monospace;font-size:11px;color:var(--text-faint)\">Install id: ": "<div style=\"margin-top:6px;font-family:ui-monospace,Menlo,monospace;font-size:11px;color:var(--text-faint)\">ID установки: ",
  "<p style=\"font-size:11px;color:var(--text-faint);line-height:1.55;margin:0\">": "<p style=\"font-size:11px;color:var(--text-faint);line-height:1.55;margin:0\">",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:18px\">": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:18px\">",
