  "settings: account": "настройки: аккаунт",
  "Unsplash Access Key": "Ключ доступа Unsplash",
  "e.g. AbCdEf123456...": "например AbCdEf123456...",
  "Go to unsplash.com/oauth/applications and create an app": "Перейдите на unsplash.com/oauth/applications и создайте приложение.",
  "Copy the <b>Access Key</b>, not the Secret Key": "Скопируйте <b>Ключ доступа</b>, а не секретный ключ.",
  "Header: <code>Authorization: Client-ID YOUR_KEY</code> - 50 req/hr on demo, 5000 req/hr in production": "Заголовок: <code>Авторизация: Client-ID YOUR_KEY</code> — 50 запросов/час в демо-версии, 5000 запросов/час в рабочей версии.",
  "Pexels API Key": "Ключ API Pexels",
  "Go to pexels.com/api and request a key": "Перейдите на pexels.com/api и запросите ключ.",
  "It is issued instantly": "Выдается моментально",
  "Header: <code>Authorization: YOUR_KEY</code> - 200 req/hr, 20K req/month": "Заголовок: <code>Авторизация: YOUR_KEY</code> - 200 заявок в час, 20 тыс. заявок в месяц.",
  "Pixabay API Key": "API-ключ Pixabay",
