  "Copy the key shown on the docs page": "Скопируйте ключ, показанный на странице документации.",
  "Images, video AND audio - 100 req/min, no monthly cap": "Изображения, видео И аудио — 100 запросов в минуту, без ежемесячного ограничения",
  "Freesound API Token": "Токен API Freesound",
  "Go to freesound.org/apiv2/apply and create an API app": "Перейдите на сайт freesound.org/apiv2/apply и создайте приложение API.",
  "Copy the <b>API Token</b>": "Скопируйте <b>API-токен</b>.",
  "500K+ CC-licensed sound effects - header: <code>Authorization: Token YOUR_KEY</code>": "500 тыс.+ звуковых эффектов под лицензией CC — заголовок: <code>Авторизация: токен YOUR_KEY</code>",
  "Jamendo Client ID": "Идентификатор клиента Jamendo",
  "e.g. abc1d2e3...": "например abc1d2e3...",
  "Go to devportal.jamendo.com and register an app": "Перейдите на devportal.jamendo.com и зарегистрируйте приложение.",
  "Copy the <b>Client ID</b>": "Скопируйте <b>Идентификатор клиента</b>.",
  "600K+ CC-licensed music tracks - free for non-commercial use": "Более 600 тысяч музыкальных треков под лицензией CC — бесплатно для некоммерческого использования.",
  "GIPHY API Key": "API-ключ GIPHY",
  "Go to developers.giphy.com and create an app": "Перейдите на сайтdevelopers.giphy.com и создайте приложение.",
