  "<span class=\"sp-acc-ico\" style=\"color:var(--red)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></span>": "<span class=\"sp-acc-ico\" style=\"color:var(--red)\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg></span>",
  "<span class=\"sp-acc-title\" style=\"color:var(--red)\">Danger Zone</span>": "<span class=\"sp-acc-title\" style=\"color:var(--red)\">Опасная зона</span>",
  "<p style=\"font-size:11px;color:var(--text-dim);margin:0 0 10px\">This will clear all saved data including profile, templates, preferences, and downloaded AI subtitle models.</p>": "<p style=\"font-size:11px;color:var(--text-dim);margin:0 0 10px\">Будут удалены все сохранённые данные, включая профиль, шаблоны, настройки и загруженные модели субтитров ИИ.</p>",
  "<div style=\"display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 10px;padding:8px 10px;border:1px solid var(--border);border-radius:6px\">": "<div style=\"display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 10px;padding:8px 10px;border:1px solid var(--border);border-radius:6px\">",
  "<span style=\"font-size:11px;color:var(--text-dim)\">AI subtitle models cache</span>": "<span style=\"font-size:11px;color:var(--text-dim)\">Кэш моделей субтитров ИИ</span>",
  "<span id=\"set-model-cache-size\" style=\"font-size:12px;font-weight:600;color:var(--text)\">&hellip;</span>": "<span id=\"set-model-cache-size\" style=\"font-size:12px;font-weight:600;color:var(--text)\">…</span>",
  "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Clear All Cache</button>": "<button id=\"set-clear-cache\" class=\"sbtn\" style=\"padding:8px 16px;width:auto;height:auto;font-size:12px;border-color:var(--red);color:var(--red)\">Очистить весь кэш</button>",
  "settings: preferences": "настройки: предпочтения",
  "<p style=\"color:var(--text-dim);font-size:12px;margin-bottom:14px\">Your profile data is used in contact presets and bulk export.</p>": "<p style=\"color:var(--text-dim);font-size:12px;margin-bottom:14px\">Данные профиля используются в пресетах контактов и массовом экспорте.</p>",
  "<button class=\"sbtn\" id=\"settings-save-profile\" style=\"margin-top:16px;width:100%;height:auto;padding:10px 16px;font-size:13px;background:var(--gold);color:#111;font-weight:600;border-radius:8px\">Save Profile</button>": "<button class=\"sbtn\" id=\"settings-save-profile\" style=\"margin-top:16px;width:100%;height:auto;padding:10px 16px;font-size:13px;background:var(--gold);color:#111;font-weight:600;border-radius:8px\">Сохранить профиль</button>",
