  "<p style=\"font-size:11px;color:var(--text-dim);margin:14px 0 6px\">Neighbor window <span style=\"color:var(--text-faint)\">(pages kept awake on each side of the active page)</span></p>": "<p style=\"font-size:11px;color:var(--text-dim);margin:14px 0 6px\">Окно соседних страниц <span style=\"color:var(--text-faint)\">(страницы, остающиеся активными по обе стороны текущей страницы)</span></p>",
  "<div class=\"ps-stat\"><div class=\"ps-stat-num\" style=\"color:var(--gold)\">": "<div class=\"ps-stat\"><div class=\"ps-stat-num\" style=\"color:var(--gold)\">",
  "settings: sleep": "настройки: сон",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Auto-save times from this browser. The latest state is stored under <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; rolling snapshots use <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:12px\">Автосохранение времени в этом браузере. Последнее состояние хранится в папке <span style=\"color:var(--text-faint);font-size:12px\">dika_autosave</span>; для прокручивающихся снимков используйте <span style=\"color:var(--text-faint);font-size:12px\">dika_versions</span>.</p>",
  "<div style=\"font-size:14px;color:var(--text)\">": "<div style=\"font-size:14px;color:var(--text)\">",
  "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">No <code>dika_autosave</code> entry yet.</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin:0\">Записи <code>dika_autosave</code> пока нет.</p>",
  "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">": "<ul id=\"settings-vh-list\" style=\"margin:0 0 12px 0;padding:0 0 0 18px;color:var(--text-dim);font-size:12px;max-height:240px;overflow-y:auto;line-height:1.4\">",
  " — <span style=\"color:var(--text-faint)\">": " — <span style=\"color:var(--text-faint)\">",
  "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">No rolling snapshots yet (they are added on each auto-save tick).</p>": "<p style=\"color:var(--text-faint);font-size:12px;margin-bottom:12px\">Прокручиваемых снимков пока нет (они добавляются при каждом автосохранении).</p>",
  "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Clears stored version snapshots (<code>dika_versions</code>). Current canvas and latest auto-save file are not removed.</span>": "<span style=\"font-size:10px;color:var(--text-faint);margin-top:6px;display:block\">Очищает сохранённые снимки версий (<code>dika_versions</code>). Текущий холст и последний файл автосохранения не удаляются.</span>",
