  "No data yet.": "Данных пока нет.",
  "Auto-save times from this browser. The latest state is stored under dika_autosave; rolling snapshots use dika_versions.": "Автосохранение времени из этого браузера. Последнее состояние хранится в файле dika_autosave; для прокатки снимков используйте dika_versions.",
  "Clear History": "Очистить историю",
  "Customize shortcuts, manage profiles, and resolve conflicts across all app modules.": "Настраивайте сочетания клавиш, управляйте профилями и устраняйте конфликты во всех модулях приложения.",
