  "Customized": "Индивидуальные",
  "Sound Effects": "Звуковые эффекты",
  "Skip Startup Wizard": "Пропустить мастер запуска",
  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "В многостраничных проектах давно не открывавшиеся страницы переводятся в фоновый режим сна, чтобы приложение работало быстрее. Их содержимое безопасно сохраняется и мгновенно возвращается при нажатии на вкладку. Текущая страница, несколько соседних страниц, а также страницы видео, бесконечного холста, слайдов и доски всегда остаются открытыми.",
  "Automatic sleep": "Автоматический сон",
  "Maximum awake pages (pages older than this number sleep)": "Максимальное число активных страниц (более старые страницы переходят в спящий режим)",
  "Neighbor window (pages kept awake on each side of the active page)": "Окно соседних страниц (страницы, которые остаются активными по обе стороны текущей страницы)",
  "AWAKE": "БОДРСТВУЮЩИЙ",
