  "TOTAL": "ОБЩИЙ",
  "Sleep all": "Спи все",
  "Upload Settings": "Настройки загрузки",
  "Configure image upload queue behavior for gallery imports.": "Настройте поведение очереди загрузки изображений для импорта галереи.",
  "Queue Settings": "Настройки очереди",
  "Concurrent Uploads": "Одновременные загрузки",
  "1 (Sequential)": "1 (последовательный)",
  "3 (Default)": "3 (по умолчанию)",
  "Number of images processed at once. Use 1 for weak servers, Unlimited for local.": "Количество обрабатываемых одновременно изображений. Используйте 1 для слабых серверов и «Без ограничений» локально.",
  "Rate Limit": "Ограничение скорости",
  "Maximum images per minute. Useful for rate-limited servers.": "Максимальное количество изображений в минуту. Полезно для серверов с ограниченной скоростью.",
  "Show progress modal": "Модальное отображение прогресса",
  "Image Settings": "Настройки изображения",
  "Max File Size": "Максимальный размер файла",
  "Files larger than this will be skipped.": "Файлы большего размера будут пропущены.",
  "Image compression is done automatically during upload (Settings → Storage → Performance).": "Сжатие изображения выполняется автоматически во время загрузки (Настройки → Хранилище → Производительность).",
  "Queue Status": "Статус очереди",
  "Multi-Product Design Platform": "Платформа дизайна нескольких товаров",
  "Built by dika.studio": "Создано dika.studio",
  "Remove everything": "Удалить все",
  "Deletes every project, page, version, uploaded file, font, brand set, saved key, setting and account on this machine, and puts the app back to how it arrived. It cannot be undone.": "Удаляет каждый проект, страницу, версию, загруженный файл, шрифт, набор брендов, сохраненный ключ, настройку и учетную запись на этом компьютере и возвращает приложение в исходное состояние. Это невозможно отменить.",
  "Export a project file first if you want to keep anything. This does not uninstall the program itself: use Windows Settings for that.": "Если вы хотите что-то сохранить, сначала экспортируйте файл проекта. При этом сама программа не удаляется: для этого используйте настройки Windows.",
  "Radial Tool Menu": "Радиальное меню инструментов",
